local SettingRefBase = require('Game.Setting.SettingRefBase')
---@class LevelGuideVo
local LevelGuideVo = Class("LevelGuideVo", SettingRefBase)

local base = SettingRefBase
local ParseUtils = CS.ParseUtils
local parse_string = parse_string
local parse_strings = parse_strings
local parse_number = parse_number
local parse_rewards = parse_rewards

function LevelGuideVo:__init()
    self.title = nil
    self.predecessorTask = nil
    self.unlockType = nil
    self.unlockId = nil
    self.unlockNum = nil
    self.taskContentType = nil
    self.taskContentId = nil
    self.taskContentNum = nil
    self.taskDesc = nil
    self.rewards = nil
    self.functionId = nil
    self.functionDesc = nil
end

function LevelGuideVo:__delete()
    self.title = nil
    self.predecessorTask = nil
    self.unlockType = nil
    self.unlockId = nil
    self.unlockNum = nil
    self.taskContentType = nil
    self.taskContentId = nil
    self.taskContentNum = nil
    self.taskDesc = nil
    self.rewards = nil
    self.functionId = nil
    self.functionDesc = nil
end

---FillVo
---@param row TableML.TableFileRow
function LevelGuideVo:FillVo(row)
    base.FillVo(self, row)

    self.title = ParseUtils.ParseLocalizeText(row, "title")
    self.predecessorTask = parse_number(row, "predecessorTask")
    self.unlockType = parse_number(row, "unlockType")
    self.unlockId = parse_number(row, "unlockId")
    self.unlockNum = parse_number(row, "unlockNum")
    self.taskContentType = parse_number(row, "taskContentType")
    self.taskContentId = parse_number(row, "taskContentId")
    self.taskContentNum = parse_number(row, "taskContentNum")

    local taskDesc = ParseUtils.ParseLocalizeText(row, "taskDesc")
    self.taskDesc = string.gsub(taskDesc, "_target_num_", "")

    self.rewards = parse_rewards(parse_string(row, "reward"), parse_string(row, "rewardNum"))
    self.functionId = parse_strings(parse_string(row, "functionId"))
    self.functionDesc = ParseUtils.ParseLocalizeText(row, "functionDesc")

end

return LevelGuideVo